SELECT b.id, b.workspace_id, b.req_id, b.name, b.status, b.owner, b.owner_user_id, b.target_branch, b.note, b.dev_at, b.test_at, b.merge_at, b.released_at, b.sort_order, b.created_at, b.updated_at, COALESCE(tc.task_count, 0) AS task_count, COALESCE(tc.done_count, 0) AS done_count FROM dev_branch b LEFT JOIN ( SELECT branch_id, COUNT(*) AS task_count, SUM(CASE WHEN board_column = 'done' THEN 1 ELSE 0 END) AS done_count FROM task WHERE workspace_id = #{workspaceId} AND deleted_at IS NULL AND branch_id IS NOT NULL GROUP BY branch_id ) tc ON tc.branch_id = b.id WHERE b.workspace_id = #{workspaceId}
AND (b.req_id = #{reqId} OR b.req_id IS NULL)
ORDER BY FIELD(b.status, 'dev', 'testing', 'merging', 'released'), b.updated_at DESC

SELECT b.id, b.workspace_id, b.req_id, b.name, b.status, b.owner, b.owner_user_id, b.target_branch, b.note, b.dev_at, b.test_at, b.merge_at, b.released_at, b.sort_order, b.created_at, b.updated_at, COALESCE(tc.task_count, 0) AS task_count, COALESCE(tc.done_count, 0) AS done_count FROM dev_branch b LEFT JOIN ( SELECT t.branch_id, COUNT(*) AS task_count, SUM(CASE WHEN t.board_column = 'done' THEN 1 ELSE 0 END) AS done_count FROM task t WHERE t.workspace_id = #{workspaceId} AND t.deleted_at IS NULL AND t.branch_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM project_member pm WHERE pm.workspace_id = t.workspace_id AND pm.project_id = t.req_id AND pm.user_id = #{viewerId} AND pm.access = 'none') GROUP BY t.branch_id ) tc ON tc.branch_id = b.id WHERE b.workspace_id = #{workspaceId}
AND (b.req_id = #{reqId} OR b.req_id IS NULL)
ORDER BY FIELD(b.status, 'dev', 'testing', 'merging', 'released'), b.updated_at DESC

mapper.sql:
b.workspace_id = #{q.workspaceId}
AND (b.req_id IS NULL OR NOT EXISTS ( SELECT 1 FROM project_member pm WHERE pm.workspace_id = b.workspace_id AND pm.project_id = b.req_id AND pm.user_id = #{q.viewerId} AND pm.access = 'none'))
AND (b.req_id = #{q.projectId} OR (b.req_id IS NULL AND NOT EXISTS ( SELECT 1 FROM task t2 WHERE t2.branch_id = b.id AND t2.deleted_at IS NULL AND t2.req_id IS NOT NULL AND t2.req_id <> #{q.projectId})))
AND b.status = #{q.status}
AND (b.owner_user_id IS NULL OR b.owner_user_id = '') AND (b.owner IS NULL OR b.owner = '')
AND b.owner_user_id = #{q.ownerUserId}
AND EXISTS (SELECT 1 FROM task tv JOIN version_task vtv ON vtv.task_id = tv.id AND vtv.workspace_id = tv.workspace_id WHERE tv.branch_id = b.id AND tv.deleted_at IS NULL AND vtv.version_id = #{q.versionId} )
AND (b.name LIKE CONCAT('%', #{q.q}, '%') OR b.target_branch LIKE CONCAT('%', #{q.q}, '%') OR b.owner LIKE CONCAT('%', #{q.q}, '%') OR EXISTS (SELECT 1 FROM task t3 JOIN version_task vt3 ON vt3.task_id = t3.id AND vt3.workspace_id = t3.workspace_id JOIN project_version pv3 ON pv3.id = vt3.version_id AND pv3.workspace_id = t3.workspace_id WHERE t3.branch_id = b.id AND t3.deleted_at IS NULL
AND pv3.name LIKE CONCAT('%', #{q.q}, '%')) OR EXISTS (SELECT 1 FROM task t4 JOIN requirement r4 ON r4.id = t4.req_id AND r4.workspace_id = t4.workspace_id WHERE t4.branch_id = b.id AND t4.deleted_at IS NULL
AND (r4.name LIKE CONCAT('%', #{q.q}, '%') OR r4.id LIKE CONCAT('%', #{q.q}, '%'))))

mapper.select:
SELECT b.id, b.workspace_id, b.req_id, b.name, b.status, b.owner, b.owner_user_id, b.target_branch, b.note, b.dev_at, b.test_at, b.merge_at, b.released_at, b.sort_order, b.created_at, b.updated_at, COALESCE(tc.task_count, 0) AS task_count, COALESCE(tc.done_count, 0) AS done_count FROM dev_branch b LEFT JOIN ( SELECT t.branch_id, COUNT(*) AS task_count, SUM(CASE WHEN t.board_column = 'done' THEN 1 ELSE 0 END) AS done_count FROM task t WHERE t.workspace_id = #{q.workspaceId} AND t.deleted_at IS NULL AND t.branch_id IS NOT NULL
AND NOT EXISTS (SELECT 1 FROM project_member pm WHERE pm.workspace_id = t.workspace_id AND pm.project_id = t.req_id AND pm.user_id = #{q.viewerId} AND pm.access = 'none')
GROUP BY t.branch_id ) tc ON tc.branch_id = b.id WHERE ORDER BY b.updated_at DESC, b.id DESC LIMIT #{q.limit} OFFSET #{q.offset}

SELECT id, workspace_id, req_id, name, status
FROM dev_branch
WHERE workspace_id = #{workspaceId}

SELECT COUNT(*) FROM dev_branch
WHERE workspace_id = #{workspaceId} AND name = #{name}
  AND (req_id = #{reqId} OR (req_id IS NULL AND #{reqId} IS NULL))
 AND id <> #{excludeId}

SELECT id, workspace_id, branch_id, action, from_status, to_status, detail, actor_name, actor_user_id, created_at
FROM dev_branch_log
WHERE branch_id = #{branchId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}
